// ---------------------------------------------------------------------------
// Remove the redundant Floating HUD intro block from the in-app HUD page.
// ---------------------------------------------------------------------------

function removeEnclosingJsxViewByNeedle_v2(text, needle, label) {
  const pos = text.indexOf(needle);
  if (pos < 0) {
    console.log(`- ${label} skipped`);
    return text;
  }
  const tokenRe = /<\/?View\b[^>]*>/g;
  const stack = [];
  let m;
  while ((m = tokenRe.exec(text)) && m.index < pos) {
    if (m[0].startsWith('</View')) {
      if (stack.length) stack.pop();
    } else if (!m[0].endsWith('/>')) {
      stack.push({start:m.index, end:tokenRe.lastIndex});
    }
  }
  if (!stack.length) {
    console.log(`- ${label} skipped: parent not found`);
    return text;
  }
  const open = stack[stack.length - 1];
  tokenRe.lastIndex = open.end;
  let depth = 1;
  let closeEnd = -1;
  while ((m = tokenRe.exec(text))) {
    if (m[0].startsWith('</View')) depth--;
    else if (!m[0].endsWith('/>')) depth++;
    if (depth === 0) {
      closeEnd = tokenRe.lastIndex;
      break;
    }
  }
  if (closeEnd < 0) {
    console.log(`- ${label} skipped: close not found`);
    return text;
  }
  const block = text.slice(open.start, closeEnd);
  if (!block.includes('ANDROID OVERLAY') || !block.includes('FLOATING HUD')) {
    console.log(`- ${label} skipped: safety mismatch`);
    return text;
  }
  console.log(`✓ ${label}`);
  return text.slice(0, open.start) + text.slice(closeEnd);
}

