// and individual information cards remain visible.
// ===========================================================================

overlay = extractEmbedded('OVERLAY_SERVICE_KT').value;
const CLEAN_SLATE_WORDMARK_BASE64 = "";

function cleanReplaceOnce(text, oldText, newText, label) {
  const count = text.split(oldText).length - 1;
  if (count !== 1) throw new Error(`TornPulse clean slate: expected 1 match for ${label}, found ${count}`);
  console.log(`✓ CLEAN SLATE ${label}`);
  return text.replace(oldText, newText);
}

// Use the exact logo supplied for this rebuild. The source image was keyed to
// transparency and cropped without redrawing the TornPulse artwork.
