// Add real Canvas-drawn line icons. This avoids font/Unicode substitutions and
// gives HEALTH the heart + pulse symbol from the approved visual direction.
if (!overlay.includes('TORNPULSE_CLEAN_SLATE_ICON_ENGINE')) {
  overlay = cleanReplaceOnce(
    overlay,
    '  private fun applyCollapsedState()',
    `  // TORNPULSE_CLEAN_SLATE_ICON_ENGINE
  private fun makeHudGlyph(kind: String, color: Int, sizeDp: Int = 18): View {
    return object : View(this) {
      private val stroke = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.STROKE
        strokeWidth = dp(2).toFloat()
        strokeCap = android.graphics.Paint.Cap.ROUND
        strokeJoin = android.graphics.Paint.Join.ROUND
        this.color = color
      }
      private val fill = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.FILL
        this.color = color
      }
      override fun onDraw(canvas: android.graphics.Canvas) {
        super.onDraw(canvas)
        val w = width.toFloat().coerceAtLeast(1f)
        val h = height.toFloat().coerceAtLeast(1f)
        val p = android.graphics.Path()
        when (kind) {
          "HEALTH" -> {
            p.moveTo(w * .50f, h * .84f)
            p.cubicTo(w * .42f, h * .75f, w * .13f, h * .58f, w * .13f, h * .34f)
            p.cubicTo(w * .13f, h * .15f, w * .34f, h * .10f, w * .50f, h * .27f)
            p.cubicTo(w * .66f, h * .10f, w * .87f, h * .15f, w * .87f, h * .34f)
            p.cubicTo(w * .87f, h * .58f, w * .58f, h * .75f, w * .50f, h * .84f)
            canvas.drawPath(p, stroke)
            val q = android.graphics.Path()
            q.moveTo(w * .16f, h * .50f); q.lineTo(w * .33f, h * .50f)
            q.lineTo(w * .40f, h * .39f); q.lineTo(w * .49f, h * .65f)
            q.lineTo(w * .58f, h * .45f); q.lineTo(w * .65f, h * .50f); q.lineTo(w * .84f, h * .50f)
            canvas.drawPath(q, stroke)
          }
          "ENERGY" -> {
            p.moveTo(w * .58f, h * .08f); p.lineTo(w * .25f, h * .52f); p.lineTo(w * .47f, h * .52f)
            p.lineTo(w * .37f, h * .92f); p.lineTo(w * .76f, h * .42f); p.lineTo(w * .53f, h * .42f); p.close()
            canvas.drawPath(p, stroke)
          }
          "NERVE" -> {
            canvas.drawCircle(w*.38f,h*.38f,w*.18f,stroke); canvas.drawCircle(w*.62f,h*.38f,w*.18f,stroke)
            canvas.drawCircle(w*.34f,h*.59f,w*.16f,stroke); canvas.drawCircle(w*.66f,h*.59f,w*.16f,stroke)
            canvas.drawLine(w*.50f,h*.22f,w*.50f,h*.76f,stroke); canvas.drawLine(w*.43f,h*.76f,w*.57f,h*.76f,stroke)
          }
          "TORN TIME" -> {
            canvas.drawCircle(w*.50f,h*.50f,w*.36f,stroke)
            canvas.drawLine(w*.50f,h*.50f,w*.50f,h*.28f,stroke); canvas.drawLine(w*.50f,h*.50f,w*.67f,h*.59f,stroke)
          }
          "DRUG" -> {
            val r = android.graphics.RectF(w*.20f,h*.30f,w*.80f,h*.70f)
            canvas.save(); canvas.rotate(-38f,w*.50f,h*.50f); canvas.drawRoundRect(r,h*.18f,h*.18f,stroke)
            canvas.drawLine(w*.50f,h*.30f,w*.50f,h*.70f,stroke); canvas.restore()
          }
          "BOOSTER" -> {
            canvas.drawRoundRect(android.graphics.RectF(w*.30f,h*.31f,w*.70f,h*.82f),w*.06f,w*.06f,stroke)
            canvas.drawRect(w*.38f,h*.18f,w*.62f,h*.31f,stroke); canvas.drawLine(w*.36f,h*.18f,w*.64f,h*.18f,stroke)
            canvas.drawLine(w*.39f,h*.55f,w*.61f,h*.55f,stroke)
          }
          "MEDICAL" -> {
            val s=w*.16f; canvas.drawRect(w*.50f-s/2,h*.19f,w*.50f+s/2,h*.81f,fill)
            canvas.drawRect(w*.19f,h*.50f-s/2,w*.81f,h*.50f+s/2,fill)
          }
          "SCANNER" -> {
            canvas.drawCircle(w*.50f,h*.50f,w*.36f,stroke); canvas.drawCircle(w*.50f,h*.50f,w*.20f,stroke)
            canvas.drawCircle(w*.50f,h*.50f,w*.055f,fill); canvas.drawLine(w*.50f,h*.50f,w*.77f,h*.31f,stroke)
          }
        }
      }
    }.apply {
      minimumWidth = dp(sizeDp)
      minimumHeight = dp(sizeDp)
    }
  }

  private fun applyCollapsedState()`,
    'canvas icon engine'
  );
}

